input.content:
workspace "Energy Manager" "C4 model of the home energy management platform" {

    model {
        homeowner = person "Homeowner" "Manages the household's energy use and costs."

        energyManager = system "Energy Manager" "Home energy management platform owned and operated by our company." {
            dashboard = softwareComponent "Dashboard Web App" "Where homeowners see consumption and costs."
            scheduling = softwareComponent "Scheduling Service" "Plans charging and heating."
            ratesLibrary = softwareComponent "Rates Library" "Shared library that computes energy prices from tariff and time of day."
            database = systemDatabase "Database" "Stores meter readings and schedules."
        }

        smartMeterProvider = system "Smart Meter Provider" "Operated by a different organization; provides live meter readings."

        homeowner -> dashboard "Manages household energy use and costs"
        dashboard -> ratesLibrary "Embeds"
        scheduling -> ratesLibrary "Embeds"
        scheduling -> smartMeterProvider "Fetches live meter readings"
        scheduling -> database "Stores meter readings and schedules"
    }

    views {
        systemContext energyManager "SystemContext" "System context view of the Energy Manager platform." {
            *
            autoLayout
        }

        container energyManager "Containers" "Container view of the Energy Manager platform." {
            *
            autoLayout
        }

        themes c4
    }
}

